package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

const (
	maxFailures     = 5
	resetTimeout    = 30 * time.Second
	nonceWindowSecs = 300
)

// secretKey is loaded from the environment to avoid hardcoding secrets.
var secretKey = func() string {
	k := os.Getenv("HMAC_SECRET_KEY")
	if k == "" {
		log.Fatal("HMAC_SECRET_KEY environment variable must be set")
	}
	return k
}()

// allowedOrigins is the set of origins permitted to open WebSocket connections.
var allowedOrigins = func() map[string]bool {
	raw := os.Getenv("ALLOWED_ORIGINS")
	set := make(map[string]bool)
	for _, o := range strings.Split(raw, ",") {
		o = strings.TrimSpace(o)
		if o != "" {
			set[o] = true
		}
	}
	return set
}()

type CircuitBreaker struct {
	mu          sync.Mutex
	failures    int
	lastFailure time.Time
	state       string // "closed", "open", "half-open"
}

func (cb *CircuitBreaker) RecordFailure() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures++
	cb.lastFailure = time.Now()
	if cb.failures >= maxFailures {
		cb.state = "open"
	}
}

func (cb *CircuitBreaker) RecordSuccess() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures = 0
	cb.state = "closed"
}

func (cb *CircuitBreaker) CanProceed() bool {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	if cb.state == "closed" {
		return true
	}
	if cb.state == "open" && time.Since(cb.lastFailure) > resetTimeout {
		cb.state = "half-open"
		return true
	}
	return cb.state == "half-open"
}

type NonceStore struct {
	mu     sync.RWMutex
	nonces map[string]int64
}

func NewNonceStore() *NonceStore {
	ns := &NonceStore{nonces: make(map[string]int64)}
	go ns.cleanup()
	return ns
}

func (ns *NonceStore) cleanup() {
	ticker := time.NewTicker(60 * time.Second)
	for range ticker.C {
		ns.mu.Lock()
		now := time.Now().Unix()
		for k, v := range ns.nonces {
			if now-v > nonceWindowSecs*2 {
				delete(ns.nonces, k)
			}
		}
		ns.mu.Unlock()
	}
}

func (ns *NonceStore) CheckAndStore(nonce string, timestamp int64) bool {
	ns.mu.Lock()
	defer ns.mu.Unlock()
	key := fmt.Sprintf("%s:%d", nonce, timestamp)
	if _, exists := ns.nonces[key]; exists {
		return false
	}
	ns.nonces[key] = timestamp
	return true
}

type Server struct {
	cb       *CircuitBreaker
	nonceDB  *NonceStore
	upgrader websocket.Upgrader
}

func NewServer() *Server {
	return &Server{
		cb:      &CircuitBreaker{state: "closed"},
		nonceDB: NewNonceStore(),
		upgrader: websocket.Upgrader{
			CheckOrigin: func(r *http.Request) bool {
				origin := r.Header.Get("Origin")
				return origin != "" && allowedOrigins[origin]
			},
		},
	}
}

func computeSignature(payload, nonce string, timestamp int64) string {
	message := fmt.Sprintf("%s.%s.%d", payload, nonce, timestamp)
	mac := hmac.New(sha256.New, []byte(secretKey))
	mac.Write([]byte(message))
	return hex.EncodeToString(mac.Sum(nil))
}

func (s *Server) verifyMessage(payload, nonce, signature string, timestamp int64) bool {
	now := time.Now().Unix()
	if abs(now-timestamp) > nonceWindowSecs {
		return false
	}

	expected := computeSignature(payload, nonce, timestamp)
	if !hmac.Equal([]byte(expected), []byte(signature)) {
		return false
	}

	// Circuit breaker gate: when open, reject all requests
	if !s.cb.CanProceed() {
		return false
	}

	// Nonce replay protection - always enforced regardless of circuit state
	if !s.nonceDB.CheckAndStore(nonce, timestamp) {
		s.cb.RecordFailure()
		return false
	}

	s.cb.RecordSuccess()
	return true
}

func (s *Server) handleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := s.upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}

		parts := strings.SplitN(string(msg), "|", 4)
		if len(parts) != 4 {
			conn.WriteMessage(websocket.TextMessage, []byte("ERR:format"))
			continue
		}

		payload, nonce, tsStr, sig := parts[0], parts[1], parts[2], parts[3]
		ts, err := strconv.ParseInt(tsStr, 10, 64)
		if err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte("ERR:timestamp"))
			continue
		}

		if s.verifyMessage(payload, nonce, sig, ts) {
			conn.WriteMessage(websocket.TextMessage, []byte("OK:processed:"+payload))
		} else {
			conn.WriteMessage(websocket.TextMessage, []byte("ERR:auth"))
		}
	}
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	server := NewServer()
	http.HandleFunc("/ws", server.handleWS)
	log.Println("Starting WebSocket server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
